--- sitzplan-page.ts ---
     1	import { Component, computed, effect, inject, input, signal, viewChildren } from '@angular/core';
     2	
     3	import { SeatMapService } from '../../../core/services/seat-map.service';
     4	import { Seat as SeatModel, SeatMap } from '../../../core/models/seat-map.model';
     5	import { Seat } from '../seat/seat';
     6	
     7	interface GridCell {
     8	  type: 'seat' | 'aisle';
     9	  seat?: SeatModel;
    10	}
    11	
    12	interface Point {
    13	  x: number;
    14	  y: number;
    15	}
    16	
    17	const MIN_ZOOM = 0.5;
    18	const MAX_ZOOM = 3;
    19	const PLACEHOLDER_ROWS = 8;
    20	const PLACEHOLDER_COLUMNS = 10;
    21	
    22	function distance(a: Point, b: Point): number {
    23	  return Math.hypot(a.x - b.x, a.y - b.y);
    24	}
    25	
    26	function midpoint(a: Point, b: Point): Point {
    27	  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
    28	}
    29	
    30	function clamp(value: number, min: number, max: number): number {
    31	  return Math.min(max, Math.max(min, value));
    32	}
    33	
    34	@Component({
    35	  selector: 'app-sitzplan-page',
    36	  imports: [Seat],
    37	  templateUrl: './sitzplan-page.html',
    38	  styleUrl: './sitzplan-page.scss'
    39	})
    40	export class SitzplanPage {
    41	  private readonly seatMapService = inject(SeatMapService);
    42	
    43	  readonly id = input.required<string>();
    44	
    45	  protected readonly seatMap = signal<SeatMap | null>(null);
    46	  protected readonly loadError = signal(false);
    47	  protected readonly selectedSeatIds = signal<ReadonlySet<string>>(new Set());
    48	  protected readonly focusedSeatId = signal<string | null>(null);
    49	  private readonly seatComponents = viewChildren(Seat);
    50	
    51	  protected readonly zoom = signal(1);
    52	  protected readonly panX = signal(0);
    53	  protected readonly panY = signal(0);
    54	
    55	  protected readonly transform = computed(() => `translate(${this.panX()}px, ${this.panY()}px) scale(${this.zoom()})`);
    56	
    57	  protected readonly columnNumbers = computed<number[]>(() => {
    58	    const map = this.seatMap();
    59	    return map ? Array.from({ length: map.columns }, (_, index) => index + 1) : [];
    60	  });
    61	
    62	  protected readonly rowsWithCells = computed<{ row: string; cells: GridCell[] }[]>(() => {
    63	    const map = this.seatMap();
    64	    if (!map) {
    65	      return [];
    66	    }
    67	
    68	    const seatByPosition = new Map<string, SeatModel>();
    69	    for (const seat of map.seats) {
    70	      seatByPosition.set(`${seat.row}:${seat.column}`, seat);
    71	    }
    72	    const aisleColumns = new Set(map.aisleColumns);
    73	
    74	    return map.rows.map((row) => ({
    75	      row,
    76	      cells: Array.from({ length: map.columns }, (_, index): GridCell => {
    77	        const column = index + 1;
    78	        if (aisleColumns.has(column)) {
    79	          return { type: 'aisle' };
    80	        }
    81	        const seat = seatByPosition.get(`${row}:${column}`);
    82	        return seat ? { type: 'seat', seat } : { type: 'aisle' };
    83	      })
    84	    }));
    85	  });
    86	
    87	  protected readonly placeholderCells = Array.from({ length: PLACEHOLDER_ROWS * PLACEHOLDER_COLUMNS });
    88	  protected readonly placeholderColumns = PLACEHOLDER_COLUMNS;
    89	
    90	  private readonly activePointers = new Map<number, Point>();
    91	  private lastPanPoint: Point | null = null;
    92	  private pinchStartDistance: number | null = null;
    93	  private pinchStartZoom = 1;
    94	  private pinchMidpoint: Point | null = null;
    95	
    96	  constructor() {
    97	    effect((onCleanup) => {
    98	      this.seatMap.set(null);
    99	      this.loadError.set(false);
   100	      this.selectedSeatIds.set(new Set());
   101	
   102	      const subscription = this.seatMapService.getSeatMap(this.id()).subscribe({
   103	        next: (seatMap) => {
   104	          this.seatMap.set(seatMap);
   105	          this.focusedSeatId.set(seatMap.seats.find((s) => s.status === 'Free')?.seatId ?? null);
   106	        },
   107	        error: () => this.loadError.set(true)
   108	      });
   109	
   110	      onCleanup(() => subscription.unsubscribe());
   111	    });
   112	  }
   113	
   114	  protected onSeatToggled(seatId: string): void {
   115	    this.focusedSeatId.set(seatId);
   116	    this.selectedSeatIds.update((current) => {
   117	      const next = new Set(current);
   118	      if (next.has(seatId)) {
   119	        next.delete(seatId);
   120	      } else {
   121	        next.add(seatId);
   122	      }
   123	      return next;
   124	    });
   125	  }
   126	
   127	  protected onGridKeydown(event: KeyboardEvent): void {
   128	    const map = this.seatMap();
   129	    const current = map?.seats.find((s) => s.seatId === this.focusedSeatId());
   130	    if (!map || !current) {
   131	      return;
   132	    }
   133	
   134	    const rowIndex = map.rows.indexOf(current.row);
   135	    let nextSeat: SeatModel | undefined;
   136	
   137	    switch (event.key) {
   138	      case 'ArrowRight':
   139	        for (let c = current.column + 1; c <= map.columns && !nextSeat; c++) {
   140	          nextSeat = this.selectableSeatAt(current.row, c);
   141	        }
   142	        break;
   143	      case 'ArrowLeft':
   144	        for (let c = current.column - 1; c >= 1 && !nextSeat; c--) {
   145	          nextSeat = this.selectableSeatAt(current.row, c);
   146	        }
   147	        break;
   148	      case 'ArrowDown':
   149	        for (let r = rowIndex + 1; r < map.rows.length && !nextSeat; r++) {
   150	          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
   151	        }
   152	        break;
   153	      case 'ArrowUp':
   154	        for (let r = rowIndex - 1; r >= 0 && !nextSeat; r--) {
   155	          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
   156	        }
   157	        break;
   158	      default:
   159	        return;
   160	    }
   161	
   162	    event.preventDefault();
   163	    if (nextSeat) {
   164	      this.focusedSeatId.set(nextSeat.seatId);
   165	      this.seatComponents()
   166	        .find((s) => s.row() === nextSeat!.row && s.column() === nextSeat!.column)
   167	        ?.focusSeat();
   168	    }
   169	  }
   170	
   171	  private selectableSeatAt(row: string, column: number): SeatModel | undefined {
   172	    const seat = this.seatMap()?.seats.find((s) => s.row === row && s.column === column);
   173	    return seat?.status === 'Free' ? seat : undefined;
   174	  }
   175	
   176	  protected onWheel(event: WheelEvent): void {
   177	    event.preventDefault();
   178	    if (event.deltaY === 0) {
   179	      return;
   180	    }
   181	    const delta = event.deltaY > 0 ? -0.1 : 0.1;
   182	    this.zoom.set(clamp(this.zoom() + delta, MIN_ZOOM, MAX_ZOOM));
   183	  }
   184	
   185	  protected onPointerDown(event: PointerEvent): void {
   186	    (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);
   187	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
   188	
   189	    if (this.activePointers.size === 1) {
   190	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
   191	    } else if (this.activePointers.size === 2) {
   192	      const [a, b] = Array.from(this.activePointers.values());
   193	      this.pinchStartDistance = distance(a, b);
   194	      this.pinchStartZoom = this.zoom();
   195	      this.pinchMidpoint = midpoint(a, b);
   196	    }
   197	  }
   198	
   199	  protected onPointerMove(event: PointerEvent): void {
   200	    if (!this.activePointers.has(event.pointerId)) {
   201	      return;
   202	    }
   203	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
   204	
   205	    if (this.activePointers.size === 2 && this.pinchStartDistance !== null && this.pinchMidpoint !== null) {
   206	      const [a, b] = Array.from(this.activePointers.values());
   207	      const currentDistance = distance(a, b);
   208	      this.zoom.set(clamp(this.pinchStartZoom * (currentDistance / this.pinchStartDistance), MIN_ZOOM, MAX_ZOOM));
   209	
   210	      const currentMidpoint = midpoint(a, b);
   211	      this.panX.update((x) => x + (currentMidpoint.x - this.pinchMidpoint!.x));
   212	      this.panY.update((y) => y + (currentMidpoint.y - this.pinchMidpoint!.y));
   213	      this.pinchMidpoint = currentMidpoint;
   214	    } else if (this.activePointers.size === 1 && event.buttons > 0 && this.lastPanPoint) {
   215	      this.panX.update((x) => x + (event.clientX - this.lastPanPoint!.x));
   216	      this.panY.update((y) => y + (event.clientY - this.lastPanPoint!.y));
   217	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
   218	    }
   219	  }
   220	
   221	  protected onPointerUp(event: PointerEvent): void {
   222	    (event.currentTarget as HTMLElement).releasePointerCapture?.(event.pointerId);
   223	    this.activePointers.delete(event.pointerId);
   224	
   225	    if (this.activePointers.size < 2) {
   226	      this.pinchStartDistance = null;
   227	      this.pinchMidpoint = null;
   228	    }
   229	
   230	    if (this.activePointers.size === 0) {
   231	      this.lastPanPoint = null;
   232	    } else {
   233	      const [remaining] = Array.from(this.activePointers.values());
   234	      this.lastPanPoint = remaining;
   235	    }
   236	  }
   237	}
